const RATES = { r0_2: 0.2, r0_8: 0.8, r1_2: 1.2, r2_1: 2.1 };
const VERDICT = {
  r0_2: ['Same sign, |m| < 1:', 'dots slide steadily toward 0.'],
  r0_8: ['Same sign, small |m|:', 'fast, steady approach to 0.'],
  r1_2: ['Sign flips, |m| < 1:', 'overshoots shrink, run converges.'],
  r2_1: ['Sign flips, |m| > 1:', 'overshoots grow, run diverges.']
};
export function evaluate({ inputs }) {
  const key = RATES[inputs.rate] !== undefined ? inputs.rate : 'r0_2';
  const eta = RATES[key];
  const k = Math.round(sdk.clamp(Number(inputs.step) || 0, 0, 8));
  const m = 1 - eta;
  const ws = [3];
  for (let i = 0; i < k; i++) ws.push(ws[i] * m);
  const L = (w) => (w * w) / 2;
  const X = sdk.linear([-7, 7], [70, 630]);
  const Y = sdk.linear([0, 25], [470, 60]);
  const o = [];
  o.push(sdk.line('xaxis', 70, Y(0), 630, Y(0)));
  o.push(sdk.line('yaxis', X(0), Y(0), X(0), Y(25)));
  [-6, -3, 0, 3, 6].forEach((w) => o.push(sdk.text('xt' + (w + 6), X(w), 492, String(w), { align: 'middle' })));
  [10, 20].forEach((l) => o.push(sdk.text('yt' + l, X(0) + 6, Y(l), 'L = ' + l)));
  o.push(sdk.text('xlab', 645, Y(0) + 4, 'w'));
  o.push(sdk.math('ylab', X(0) + 10, 34, 'L(w) = \\tfrac{1}{2}w^2'));
  const curve = sdk.sample(L, -7, 7, 140).map(([w, l]) => [X(w), Y(l)]);
  o.push(sdk.polyline('curve', curve, { role: 'neutral' }));
  const pts = ws.map((w) => [X(w), Y(L(w))]);
  if (pts.length > 1) o.push(sdk.polyline('path', pts, { role: 'prediction' }));
  const curRole = key === 'r2_1' ? 'warning' : 'success';
  pts.forEach((p, i) => {
    const last = i === pts.length - 1;
    o.push(sdk.circle('pt' + i, p[0], p[1], last ? 16 : 10, { role: last ? curRole : 'learner' }));
  });
  const cur = pts[pts.length - 1];
  o.push(sdk.text('curlab', cur[0] + 12, cur[1] - 14, 'step ' + k));
  const wk = ws[ws.length - 1];
  const px = 670;
  o.push(sdk.math('rule', px, 50, 'w_{k+1} = w_k - \\eta L\'(w_k) = (1-\\eta)\\,w_k'));
  o.push(sdk.math('mult', px, 84, '\\eta = ' + eta + ',\\; m = 1-\\eta = ' + sdk.format(m, 1)));
  o.push(sdk.text('v1', px, 118, VERDICT[key][0], { role: curRole }));
  o.push(sdk.text('v2', px, 140, VERDICT[key][1], { role: curRole }));
  o.push(sdk.text('now', px, 176, 'Step ' + k + ':  w = ' + sdk.format(wk, 3) + ',  L = ' + sdk.format(L(wk), 3)));
  o.push(sdk.text('thead', px, 214, 'k    w_k        L(w_k)'));
  ws.forEach((w, i) => o.push(sdk.text('row' + i, px, 238 + i * 22, i + ':   ' + sdk.format(w, 3) + '     ' + sdk.format(L(w), 3))));
  return {
    frame: sdk.frame(o, { width: 960, height: 540, readouts: [
      { id: 'w_now', value: wk }, { id: 'loss_now', value: L(wk) }, { id: 'multiplier', value: m }
    ] }),
    quantities: { w_now: wk, loss_now: L(wk), multiplier: m, eta: eta, step_k: k }
  };
}

